{"id":"0dfeb65f-8480-41d7-a639-4fede837e41a","inserted_at":"2026-07-15T09:03:28.505118+00:00","updated_at":"2026-07-15T09:03:28.505118+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- =========================================================================================\r\n-- FIX BUG MAPPA: VISTA FRONTEND MANCANTE\r\n-- =========================================================================================\r\n\r\n-- 1. Ripristino la colonna tenant_id che era stata creata a mano su Supabase in passato\r\nALTER TABLE public.pois ADD COLUMN IF NOT EXISTS tenant_id TEXT DEFAULT 'taranto';\r\n\r\n-- 2. Ricreiamo la View \"vw_pois_frontend\" che la mappa usa per scaricare i POI.\r\n-- Anche questa View era stata creata manualmente su Supabase in passato per decodificare\r\n-- le coordinate spaziali PostGIS (coords) in lat/lng semplici per il frontend (map.tsx).\r\nCREATE OR REPLACE VIEW public.vw_pois_frontend AS\r\nSELECT \r\n    p.id,\r\n    p.name,\r\n    p.category,\r\n    p.layer_name,\r\n    p.xp_reward,\r\n    p.checkin_radius,\r\n    p.crowd_level,\r\n    p.has_water,\r\n    p.is_accessible,\r\n    p.is_recommended,\r\n    p.loto_quota_max,\r\n    p.current_occupancy,\r\n    p.pending_occupancy,\r\n    p.recommended_parking_id,\r\n    p.parking_bonus_xp,\r\n    p.p_iva,\r\n    p.pec,\r\n    p.tenant_id,\r\n    p.is_active,\r\n    -- Decodifica PostGIS essenziale per map.tsx\r\n    ST_Y(p.coords::geometry) AS lat,\r\n    ST_X(p.coords::geometry) AS lng\r\nFROM public.pois p;\r\n\r\n-- 3. Riapplichiamo esplicitamente i permessi per sicurezza\r\nGRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO postgres, anon, authenticated, service_role;\r\nGRANT ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public TO postgres, anon, authenticated, service_role;\r\nGRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO postgres, anon, authenticated, service_role;","content_id":"0dfeb65f-8480-41d7-a639-4fede837e41a","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
